import json
import sys
import time
import types

NS = types.SimpleNamespace
_sleeps = []


def _sleep(seconds):
    _sleeps.append(seconds)
    if len(_sleeps) == 3:
        print("... and so on, every second, all weekend")
        raise SystemExit(0)


time.sleep = _sleep


class SpendCapReached(Exception):
    pass


def requeue(ticket, delay):
    print(f"requeued in {delay}s: {ticket[:30]}")


class _Response:
    def __init__(self, status, body, headers=None):
        self.status_code = status
        self._body = body
        self.headers = headers or {}

    def json(self):
        return self._body


class APIError(Exception):
    pass


class APIStatusError(APIError):
    def __init__(self, message, *, response):
        super().__init__(message)
        self.response = response
        self.status_code = response.status_code


class BadRequestError(APIStatusError):
    pass


class AuthenticationError(APIStatusError):
    pass


class PermissionDeniedError(APIStatusError):
    pass


class NotFoundError(APIStatusError):
    pass


class RateLimitError(APIStatusError):
    pass


class InternalServerError(APIStatusError):
    pass


class APIConnectionError(APIError):
    pass


_PREFILL = ("This model does not support assistant message prefill. "
            "The conversation must end with a user message.")


def _create(*, model, max_tokens, messages, **kwargs):
    if messages[-1]["role"] == "assistant":
        body = {"type": "error",
                "error": {"type": "invalid_request_error", "message": _PREFILL},
                "request_id": "req_011CSHoEeqs5C35K2UUqR7Fy"}
        raise BadRequestError(f"Error code: 400 - {json.dumps(body)}",
                              response=_Response(400, body))
    body = {"type": "error",
            "error": {"type": "rate_limit_error", "message": "Rate limited"}}
    raise RateLimitError("Error code: 429", response=_Response(
        429, body, {"retry-after": "20"}))


class _Anthropic:
    def __init__(self, **kwargs):
        self.messages = NS(create=_create)


sys.modules["anthropic"] = NS(
    Anthropic=_Anthropic, APIError=APIError, APIStatusError=APIStatusError,
    BadRequestError=BadRequestError, AuthenticationError=AuthenticationError,
    PermissionDeniedError=PermissionDeniedError, NotFoundError=NotFoundError,
    RateLimitError=RateLimitError, InternalServerError=InternalServerError,
    APIConnectionError=APIConnectionError,
)
